// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/auth/login", wrapper.Login)
	router.GET(options.BaseURL+"/auth/me", wrapper.GetCurrentUser)
	router.GET(options.BaseURL+"/hazard-types", wrapper.ListHazardTypes)
	router.POST(options.BaseURL+"/hazard-types", wrapper.CreateHazardType)
	router.DELETE(options.BaseURL+"/hazard-types/:id", wrapper.DeleteHazardType)
	router.PUT(options.BaseURL+"/hazard-types/:id", wrapper.UpdateHazardType)
	router.GET(options.BaseURL+"/hazards", wrapper.ListHazards)
	router.POST(options.BaseURL+"/hazards", wrapper.CreateHazard)
	router.GET(options.BaseURL+"/hazards/stats", wrapper.GetHazardStats)
	router.DELETE(options.BaseURL+"/hazards/:id", wrapper.DeleteHazard)
	router.GET(options.BaseURL+"/hazards/:id", wrapper.GetHazard)
	router.PUT(options.BaseURL+"/hazards/:id", wrapper.UpdateHazard)
	router.POST(options.BaseURL+"/images", wrapper.UploadImage)
	router.GET(options.BaseURL+"/images/:id", wrapper.GetImage)
	router.GET(options.BaseURL+"/images/:id/thumbnail", wrapper.GetImageThumbnail)
	router.GET(options.BaseURL+"/units", wrapper.ListUnits)
	router.POST(options.BaseURL+"/units", wrapper.CreateUnit)
	router.DELETE(options.BaseURL+"/units/:id", wrapper.DeleteUnit)
	router.PUT(options.BaseURL+"/units/:id", wrapper.UpdateUnit)
}
